def VTask.replaceVertex {V : Type u_1} (G : SimpleGraph V) (s t : V) [DecidableEq V] : SimpleGraph V :=
  { adj := fun u v => if u = t then G.Adj s v else if v = t then G.Adj s u else G.Adj u v }
  where
  loopless : ∀ (v : V), ¬(adj v v)
    | v =>
      by
        dsimp only [adj]
        by_cases h : v = t <;> simp_all [h]
        <;>
          (try contradiction) <;>
          (try {
            have h₁ := G.loopless v
            simp_all [h]
          }) <;>
          (try {
            have h₁ := G.loopless s
            simp_all [h]
          })
  symm : ∀ {u v : V}, adj u v → adj v u
    | u v h =>
      dsimp only [adj] at h ⊢
      by_cases hu : u = t <;> by_cases hv : v = t <;> simp_all [hu, hv]
      <;>
        (try {
          simp_all [G.symm]
          <;> aesop
        }) <;>
        (try {
          have h₁ := G.symm
          simp_all [h₁]
          <;> aesop
        }) <;>
        (try {
          aesop
        })
